export const opportunities: Opportunity[] = [...currentOpportunities,...followupOpportunities].map(item=>({...item,relatedTags:relatedTagsFor(item)}));

export function nextDeadline(o: Opportunity, now: number) {
  return o.sessions?.find(s => Date.parse(s.deadline) >= now)?.deadline ?? o.deadline;
}
export function isClosed(o: Opportunity, now: number) { return !o.ongoing && Date.parse(o.deadline) < now; }
export function dateLabel(value: string) { return new Date(value).toLocaleDateString('ja-JP', {timeZone:'Asia/Tokyo',year:'numeric',month:'numeric',day:'numeric'}); }
